import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Avatar, Box, Card, CardContent, CardHeader, Typography } from '@mui/material';
import { formatDistanceToNow } from 'date-fns';
import { fr } from 'date-fns/locale';
import LikeButton from '../Likes/LikeButton';
import CommentIcon from '@mui/icons-material/Comment';
import { Publication } from '../../types';

interface PublicationCardProps {
    publication: Publication;
    currentUserId: number;
}

const PublicationCard: React.FC<PublicationCardProps> = ({ publication, currentUserId }) => {
    const navigate = useNavigate();

    const avatarUrl = publication.photo_profil
        ? `/icons/${publication.photo_profil}`
        : '/icons/green.jpg';

    const photoUrl = publication.photo_publier
        ? `http://localhost:8080/uploads/${publication.photo_publier}`
        : null;

    return (
        <Card sx={{ 
            mb: 2, 
            borderRadius: 3, 
            overflow: 'hidden',
            mx: { xs: 0, sm: 1, md: 2 },
            display: 'flex',
            flexDirection: 'column',
            height: 'auto'
        }}>
            {/* Header fixe */}
            <CardHeader
                avatar={
                    <Avatar src={avatarUrl} sx={{ width: 48, height: 48 }} />
                }
                title={`@${publication.pseudo}`}
                subheader={formatDistanceToNow(new Date(publication.date), {
                    addSuffix: true,
                    locale: fr
                })}
                sx={{
                    px: { xs: 1, sm: 1.5, md: 2 },
                    pt: 1,
                    pb: 0.5,
                    flexShrink: 0
                }}
            />

            {/* Partie centrale scrollable */}
            <CardContent sx={{ 
                px: { xs: 1, sm: 1.5, md: 2 }, 
                py: 0.5,
                flex: 1,
                overflow: 'auto',
                '&::-webkit-scrollbar': {
                    width: '6px'
                },
                '&::-webkit-scrollbar-track': {
                    background: '#f1f1f1',
                    borderRadius: '10px'
                },
                '&::-webkit-scrollbar-thumb': {
                    background: '#773399',
                    borderRadius: '10px',
                    '&:hover': {
                        background: '#5a2a7a'
                    }
                }
            }}>
                <Box sx={{ display: 'flex', gap: 1.5, alignItems: 'center' }}>
                    {/* Texte à gauche avec marges internes */}
                    {publication.contenu && (
                        <Typography 
                            variant="body1" 
                            sx={{
                                flex: 1,
                                textAlign: 'center',
                                fontFamily: 'Poppins, sans-serif',
                                lineHeight: 1.5,
                                whiteSpace: 'pre-wrap',
                                wordBreak: 'break-word',
                                fontSize: '0.9rem',
                                mx: 2,
                                my: 1
                            }}
                        >
                            {publication.contenu}
                        </Typography>
                    )}

                    {/* Image à droite avec marge à droite égale à celle du texte */}
                    {photoUrl && (
                        <Box
                            sx={{
                                width: 180,
                                height: 270,
                                flexShrink: 0,
                                bgcolor: '#f5f5f5',
                                borderRadius: 2,
                                overflow: 'hidden',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                mr: 2
                            }}
                        >
                            <img
                                src={photoUrl}
                                alt="Publication"
                                style={{
                                    width: '100%',
                                    height: '100%',
                                    objectFit: 'cover'
                                }}
                            />
                        </Box>
                    )}
                </Box>
            </CardContent>

            {/* Boutons fixes */}
            <CardContent sx={{ 
                px: { xs: 1, sm: 1.5, md: 2 }, 
                pt: 0, 
                pb: 1,
                flexShrink: 0
            }}>
                <Box display="flex" alignItems="center" gap={1.5}>
                    <LikeButton
                        userId={currentUserId}
                        publicationId={publication.id}
                        initialCount={publication.nombre_like}
                    />

                    <Box
                        display="flex"
                        alignItems="center"
                        gap={0.5}
                        sx={{ cursor: 'pointer' }}
                        onClick={() => navigate(`/commentaires?pubId=${publication.id}&userId=${currentUserId}`)}
                    >
                        <CommentIcon sx={{ color: '#666', fontSize: 20 }} />
                        <Typography variant="body2" color="text.secondary">
                            {publication.nombre_commentaire}
                        </Typography>
                    </Box>
                </Box>
            </CardContent>
        </Card>
    );
};

export default PublicationCard;
